import unittest

from hourglass.rounding import round_span, rounded_labels
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        got = round_span(parse_span("09:07-17:08"), 15)
        self.assertEqual(got, parse_span("09:00-17:15"))

    def test_halfway_rounds_up(self):
        got = round_span(Span(435, 600), 30)
        self.assertEqual(got.start, 450)

    def test_end_can_reach_midnight(self):
        got = round_span(parse_span("20:00-23:58"), 5)
        self.assertEqual(got.end, 24 * 60)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(parse_span("09:01-09:04"), 15)

class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_span(Span(0, 60), step)

    def test_good_steps_accepted(self):
        for step in (1, 5, 15, 30, 60):
            round_span(Span(0, 120), step)

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:02-17:14")]
        got = rounded_labels(spans, 15)
        self.assertEqual(got, ["09:00-17:15 (8h 15m)"])

    def test_one_label_per_span(self):
        spans = [Span(0, 60), Span(120, 240)]
        got = rounded_labels(spans, 60)
        want = ["00:00-01:00 (1h 0m)"]
        want.append("02:00-04:00 (2h 0m)")
        self.assertEqual(got, want)

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])
